}
// 실제 조회 자료의 수명만 빌리며 constructor는 지도/난수를 변경하지 않는다.
RawTerrainGrowth::RawTerrainGrowth(RawTerrainContext& context,const ChunkMap& chunks,const TerrainContextGlobals& globals)
