#include <bit>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <utility>

namespace netstorm::o {
namespace {
// 원본 raw 슬롯의 타입/상태 바이트와 HP 필드의 위치다(HP는 패치 DWORD, CD WORD).
constexpr std::size_t kType=10,kState=11,kHp=26;
// 지갑을 올리는 하한과 SP를 고정할 때의 판본별 값이다(패치 0x500ff8, CD 0x47c35000).
