        if ((extra&kFirstPop)==0) normalized|=(extra&9)==0 ? 1U : ((extra&1)!=0 ? 2U : 0U)|((extra&8)!=0 ? 4U : 0U);
        if ((normalized&8)==0) normalized|=0x10;
