                auto& spot=spots_[static_cast<std::size_t>(cy*kWorldCells+cx)];
                if (genus) {
                    if (patch && (spot&genus)) return RawPopResult::Overlap;
                    spot=static_cast<std::uint8_t>(spot|genus);
                }
                // 겹침에서 앞서 반환한 칸은 통지하지 않는다. 양 옆면의 모서리는 제외한다.
