// raw 가상 주소를 호스트 포인터로 해석하지 않고 읽는다.
std::uint32_t Vtable(std::span<const std::uint8_t> bytes) {
    std::uint32_t value=0;
    // little endian DWORD를 조합한다.
    for (std::size_t i=0;i<4;++i) value|=static_cast<std::uint32_t>(bytes[i])<<(8*i);
    return value;
}
